The three points $(3,-5)$, $(-a + 2, 3)$, and $(2a+3,2)$ lie on the same line.  What is $a$?

Put your final answer within \boxed{}.

#include <iostream>
#include <cmath>

using namespace std;

int main() {
    double x1 = 3;
    double y1 = -5;
    double x2 = -a + 2;
    double y2 = 3;
    double x3 = 2*a + 3;
    double y3 = 2;

    double slope1 = (y2 - y1) / (x2 - x1);
    double slope2 = (y3 - y2) / (x3 - x2);

    if (slope1 == slope2) {
        cout << "The three points lie on the same line." << endl;
        cout << "The value of a is: " << a << endl;
    } else {
        cout << "The three points do not lie on the same line." << endl;
    }

    return 0;
}

