Find all real values of $x$ that satisfy $\frac{1}{x(x+1)}-\frac{1}{(x+1)(x+2)} < \frac{1}{3}.$ (Give your answer in interval notation.)

Put your final answer within \boxed{}.

#include <iostream>
#include <cmath>
using namespace std;

int main() {
    double x;
    double left_bound = 0;
    double right_bound = 1;
    double tolerance = 0.0001;

    while (true) {
        x = (left_bound + right_bound) / 2;
        double left_side = 1 / (x * (x + 1)) - 1 / ((x + 1) * (x + 2));
        double right_side = 1 / 3;

        if (abs(left_side - right_side) < tolerance) {
            cout << "The solution is: " << x << endl;
            break;
        } else if (left_side > right_side) {
            left_bound = x;
        } else {
            right_bound = x;
        }
    }

    return 0;
}

